    freq = {}
    for s in test_list:
        freq[s] = freq.get(s, 0) + 1

    total_pairs = 0
    seen = set()

    for s, f in freq.items():
        if s in seen:
            continue
        seen.add(s)

        rev_s = s[::-1]
        if rev_s == s:
            total_pairs += f * (f - 1) // 2
