def max_Product(arr):
    # Initialize with the first two elements
    if arr[0] > arr[1]:
        max1, max2 = arr[0], arr[1]
        min1, min2 = arr[1], arr[0]
    else:
        max1, max2 = arr[1], arr[0]
        min1, min2 = arr[0], arr[1]

    # Single pass to find the two largest and two smallest numbers
    for x in arr[2:]:
        if x > max1:
            max2, max1 = max1, x
        elif x > max2:
            max2 = x

        if x < min1:
            min2, min1 = min1, x
        elif x < min2:
            min2 = x

    prod_max = max1 * max2
    prod_min = min1 * min2

    # The highest product comes from either two large positives 
    # or two large negatives (since neg * neg > 0)
    if prod_max >= prod_min:
        return tuple(sorted((max1, max2)))
    else:
