def sumofFactors(n: int) -> int:
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"

    if n == 0 or n % 2 != 0:
        return 0

    total = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i % 2 == 0:
                total += i

            d = n // i
            if d != i and d % 2 == 0:
