def max_sum(arr):
    n = len(arr)

    inc = [x for x in arr]
    dec = [x for x in arr]

    # Compute maximum increasing sums ending at each index
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Compute maximum decreasing sums starting at each index
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Combine increasing and decreasing sums around each possible peak
    return max(inc[i] + dec[i] - arr[i] for i in range(n))
```

