def odd_Equivalent(s: str, n: int) -> int:
    L = len(s)
    if L == 0 or n == 0:
        return 0

    ones_count = s.count('1')
    full_cycles = n // L
    remainder = n % L

    return full_cycles * ones_count + s[:remainder].count('1')
```

