def shell_sort(lst):
    n, gap = len(lst), len(lst) // 2
    while gap > 0:
        for i in range(gap, n):
            j, tmp = i, lst[i]
            while j >= gap and lst[j - gap] > tmp:
                lst[j] = lst[j - gap]
                j -= gap
            lst[j] = tmp
        gap //= 2
    return lst
```

