def max_sub_array_sum_repeated(a, n, k):
    if not k: return 0
    def kadane(A):
        m = c = -float('inf')
        for v in A: c = max(v, c + v); m = max(m, c)
        return m

    total = sum(a)
    if k == 1 or total <= 0:
        return kadane(a * min(k, 2))

    p = s = mp = ms = -float('inf')
    for x in a: p += x; mp = max(mp, p)
    for x in reversed(a): s += x; ms = max(ms, s)

    return max(kadane(a * min(k, 2)), mp + (k - 2) * total + ms)
```

